SELECT arrayFilter(tag -> tag.1 != '__name__', clamp_child.tags) AS tags, clamp_child.timestamp AS timestamp, if(isNaN(clamp_child.value) OR isNaN(0) OR isNaN(10), nan, greatest(0, least(10, clamp_child.value))) AS value FROM (SELECT series.tags AS tags, max(d.timestamp) AS timestamp, argMax(d.value, d.timestamp) AS value FROM timeSeriesData(`observability`.`prometheus`) AS d INNER JOIN (
    SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {clamp_child_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({clamp_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({clamp_child_required_end_ms:Int64})
) AS series ON d.id = series.id WHERE d.timestamp >= fromUnixTimestamp64Milli({clamp_child_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({clamp_child_required_end_ms:Int64}) GROUP BY d.id, series.tags HAVING NOT isNaN(value) ORDER BY tags) AS clamp_child WHERE NOT (10 < 0)
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
